import{_ as e,o as i,c as o,ag as a}from"./chunks/framework.HG0H2VLS.js";const u=JSON.parse('{"title":"ControlRecordScreen — content classification","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/prototypes/ControlRecordScreen/ControlRecordScreen.classification.md","filePath":"public/demos/src/prototypes/ControlRecordScreen/ControlRecordScreen.classification.md"}'),r={name:"public/demos/src/prototypes/ControlRecordScreen/ControlRecordScreen.classification.md"};function n(d,t,s,c,l,h){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="controlrecordscreen-—-content-classification" tabindex="-1">ControlRecordScreen — content classification <a class="header-anchor" href="#controlrecordscreen-—-content-classification" aria-label="Permalink to &quot;ControlRecordScreen — content classification&quot;">​</a></h1><p><strong>Status: PROVISIONAL.</strong> Every row was read off the live v2 screens on 2026-09-22 and is awaiting Shaz&#39;s field inventory (task #853324). The rule being applied:</p><ul><li><strong>editable → main column.</strong> A field is editable if and only if the <em>Edit</em> screen renders a control for it. Read from the screen definitions, not inferred from how it looks on View.</li><li><strong>compact fact → right sidebar.</strong> No control anywhere, and short enough to read in a 320px column.</li><li><strong>wide evidence → tabs (model A) / compressed summary (model B).</strong> No control anywhere, but needs more width than a sidebar has: a chart, a multi-column related-record table, a child listing.</li></ul><p>The third bucket is the finding. The original proposal had two buckets; Article&#39;s view-only content does not fit in one column, so it had to split. Article Icon has no wide evidence at all, which is why models A and B render it identically and it is built once.</p><p>Anything Shaz contradicts moves between <code>main</code> and <code>facts</code> in <code>_generate.mjs</code>, all six screens regenerate, and the affected frames are re-pushed with a bumped <code>v&lt;n&gt;</code>.</p><hr><h2 id="article-—-control-standard-item-edit" tabindex="-1">Article — <code>/control/standard-item-edit</code> <a class="header-anchor" href="#article-—-control-standard-item-edit" aria-label="Permalink to &quot;Article — `/control/standard-item-edit`&quot;">​</a></h2><p>19 sections on the live screen. 13 editable, 5 compact facts, 3 wide evidence (Stats and SEO Health Check split across buckets — the stats panel is wide, the health-check advisory list is short).</p><h3 id="main-column-—-editable-13-sections" tabindex="-1">Main column — editable (13 sections) <a class="header-anchor" href="#main-column-—-editable-13-sections" aria-label="Permalink to &quot;Main column — editable (13 sections)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Fields</th></tr></thead><tbody><tr><td>Navigation</td><td>Zone*, Section*, Sort Order, Multi Display, Priority</td></tr><tr><td>Introduction</td><td>Title*, Screen Name, Alternative Title, Thumbnail</td></tr><tr><td>Main Body</td><td>Alignment, Main Image, Audio Version (MP3), Blog Intro, Blog Entry</td></tr><tr><td>Topics</td><td>Category Topic, Topics and Keywords</td></tr><tr><td>SEO</td><td>Page Title, Page Description</td></tr><tr><td>Social</td><td>Shareline 1–3</td></tr><tr><td>Article Questions</td><td>Question 1–5</td></tr><tr><td>Summary</td><td>Summary</td></tr><tr><td>Publication</td><td>Creator, Related Authors, Publish Start, Publish End, Embargo End, Syndication, Live, Private, Send Via Content / Interest Subscription, Hide From Search Results, Exclude From AI Index, Moderated</td></tr><tr><td>Security</td><td>Content Security Right</td></tr><tr><td>Advanced</td><td>External Article ID, Article Type, Multimedia</td></tr><tr><td>Geo Targeting</td><td>Geo Targeting Type, Countries</td></tr><tr><td>Comments And Ratings</td><td>Hide Comments And Ratings</td></tr></tbody></table><p>* compulsory on the v2 screen.</p><p><strong>Note on Advanced:</strong> <em>Article Code</em> (626353) sits in this section on the v2 screen but is a system-assigned identifier with no control. It moves to the sidebar under <strong>Record</strong>. This is the clearest single example of the rule doing useful work — it separates the record&#39;s identity from the things you can change about it.</p><h3 id="right-sidebar-—-compact-facts-5-blocks" tabindex="-1">Right sidebar — compact facts (5 blocks) <a class="header-anchor" href="#right-sidebar-—-compact-facts-5-blocks" aria-label="Permalink to &quot;Right sidebar — compact facts (5 blocks)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Block</th><th>Contents</th></tr></thead><tbody><tr><td>Record</td><td>Article Code, Batch Reference</td></tr><tr><td>SEO health</td><td>3 advisories (no sharelines, no topics, no subheadings)</td></tr><tr><td>Meta information</td><td>Publisher, Creator, Rights, Date, Language — all derived</td></tr><tr><td>Index status</td><td>Site Search, Affino.com Assistant</td></tr><tr><td>Audit</td><td>Created, Created by, Last updated, Last updated by, Last view, Impressions + <em>View audit trail</em></td></tr></tbody></table><p><strong>Note on Creator:</strong> it appears twice — as an editable picker under Publication, and as a derived value under Meta Information. That is how the v2 screen has it, and the two are genuinely different things (the assigned author vs. the Dublin Core metadata field). Kept as-is rather than silently deduplicated; flag for Shaz to confirm they are separate fields in the data.</p><h3 id="wide-evidence-3-blocks" tabindex="-1">Wide evidence (3 blocks) <a class="header-anchor" href="#wide-evidence-3-blocks" aria-label="Permalink to &quot;Wide evidence (3 blocks)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Block</th><th>Why it cannot live in a 320px sidebar</th></tr></thead><tbody><tr><td>Performance</td><td>4 metrics + a 12-point impressions chart + 7 account chips</td></tr><tr><td>Recent viewers</td><td>5 contacts with name, role, account, relative time — 4 columns minimum</td></tr><tr><td>Article steps</td><td>23 rows with title, type, sort order, creator; own paging; own Lookup action</td></tr></tbody></table><p>Model A puts these in tabs. Model B compresses each to a 3-row summary plus a link out to the screen that already shows them in full (Site Analysis, Contacts, the Article Steps listing).</p><hr><h2 id="article-icon-—-control-article-icon" tabindex="-1">Article Icon — <code>/control/article-icon</code> <a class="header-anchor" href="#article-icon-—-control-article-icon" aria-label="Permalink to &quot;Article Icon — `/control/article-icon`&quot;">​</a></h2><p>2 sections. This is the floor case, and the point of including it.</p><table tabindex="0"><thead><tr><th>Bucket</th><th>Contents</th></tr></thead><tbody><tr><td>Main column — editable</td><td><strong>Main:</strong> Name*, Article Profile, Target Section, Section, Icon, Description</td></tr><tr><td>Sidebar — compact facts</td><td><strong>Audit:</strong> Created, Created by, Last updated, Last updated by</td></tr><tr><td>Wide evidence</td><td><em>none</em></td></tr></tbody></table><p><strong>What this screen exposes.</strong> With one 4-row fact block, the sidebar is mostly empty and the main column is 6 fields — so a 1600px screen is largely white space with a small form on the left and a small card on the right. The pattern does not fail, but it does not earn its keep either. Whether that matters depends entirely on how common this shape is across the ~1,053 control screens, which is exactly what the census half of Shaz&#39;s brief is for. Do not settle A vs B from the Article screen alone.</p><hr><h2 id="not-yet-classified" tabindex="-1">Not yet classified <a class="header-anchor" href="#not-yet-classified" aria-label="Permalink to &quot;Not yet classified&quot;">​</a></h2><p>The other two exemplars Mark named are in Shaz&#39;s brief but not in this build:</p><ul><li><strong><code>/control/edition</code></strong> — ~6 sections. Carries a large emphasised stat (<code>Circulation 0</code>) inside an otherwise ordinary field section, and a screen-level action (<em>Calculate Circulation</em>) in the header. Neither has a home in the current model: an emphasised metric is not a field, and a screen action is not a record action. <code>.crs-stat</code> exists for the former; the latter belongs in <code>.cc-header__actions</code>.</li><li><strong><code>/control/directory-article-profile</code></strong> — 4 sections, one of which (<em>Directory Article Limit</em>) is an embedded child table sitting mid-form, and one of which (<em>Text Items</em>) is ~40 label-override pairs. The child table is wide evidence that is also <em>editable</em>, which the current three-bucket model does not cover. Worth resolving before the pattern is generalised.</li></ul>',27)])])}const p=e(r,[["render",n]]);export{u as __pageData,p as default};
